// Package api implements the HTTP interface of the notes service.
package api

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"strings"

	"notes/internal/store"
)

const (
	maxBodyBytes = 32 << 20
	defaultLimit = 100
	maxLimit     = 100
)

// Server routes HTTP requests to the note store.
type Server struct {
	store *store.Store
	log   *slog.Logger
}

// New returns an http.Handler serving the notes API.
func New(st *store.Store, log *slog.Logger) *Server {
	return &Server{store: st, log: log}
}

// ServeHTTP dispatches by path, answering 404 for unknown paths and 405 for unsupported methods.
// Routing is done by hand so that every error, including 404 and 405, carries a JSON body.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	switch {
	case path == "/health":
		s.route(w, r, map[string]http.HandlerFunc{http.MethodGet: s.health})
	case path == "/notes":
		s.route(w, r, map[string]http.HandlerFunc{
			http.MethodGet:  s.listNotes,
			http.MethodPost: s.createNote,
		})
	case strings.HasPrefix(path, "/notes/"):
		id, ok := parsePositiveID(strings.TrimPrefix(path, "/notes/"))
		if !ok {
			writeError(w, http.StatusNotFound, "note not found")
			return
		}
		s.route(w, r, map[string]http.HandlerFunc{
			http.MethodGet:    func(w http.ResponseWriter, r *http.Request) { s.getNote(w, r, id) },
			http.MethodPut:    func(w http.ResponseWriter, r *http.Request) { s.updateNote(w, r, id) },
			http.MethodDelete: func(w http.ResponseWriter, r *http.Request) { s.deleteNote(w, r, id) },
		})
	case path == "/stats":
		s.route(w, r, map[string]http.HandlerFunc{http.MethodGet: s.stats})
	case path == "/tags":
		s.route(w, r, map[string]http.HandlerFunc{http.MethodGet: s.tags})
	default:
		writeError(w, http.StatusNotFound, "not found")
	}
}

func (s *Server) route(w http.ResponseWriter, r *http.Request, methods map[string]http.HandlerFunc) {
	if h, ok := methods[r.Method]; ok {
		h(w, r)
		return
	}
	if r.Method == http.MethodHead {
		if h, ok := methods[http.MethodGet]; ok {
			h(w, r)
			return
		}
	}
	allow := make([]string, 0, len(methods))
	for _, m := range []string{http.MethodGet, http.MethodPost, http.MethodPut, http.MethodDelete} {
		if _, ok := methods[m]; ok {
			allow = append(allow, m)
		}
	}
	w.Header().Set("Allow", strings.Join(allow, ", "))
	writeError(w, http.StatusMethodNotAllowed, "method not allowed")
}

func (s *Server) health(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	_, _ = io.WriteString(w, "ok")
}

func (s *Server) createNote(w http.ResponseWriter, r *http.Request) {
	in, ok := s.readNoteInput(w, r)
	if !ok {
		return
	}
	n, err := s.store.Create(r.Context(), in.Title, in.Body, in.Tags)
	if err != nil {
		s.internalError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, n)
}

func (s *Server) getNote(w http.ResponseWriter, r *http.Request, id int64) {
	n, err := s.store.Get(r.Context(), id)
	if s.storeError(w, err) {
		return
	}
	writeJSON(w, http.StatusOK, n)
}

func (s *Server) updateNote(w http.ResponseWriter, r *http.Request, id int64) {
	in, ok := s.readNoteInput(w, r)
	if !ok {
		return
	}
	n, err := s.store.Update(r.Context(), id, in.Title, in.Body, in.Tags)
	if s.storeError(w, err) {
		return
	}
	writeJSON(w, http.StatusOK, n)
}

func (s *Server) deleteNote(w http.ResponseWriter, r *http.Request, id int64) {
	if s.storeError(w, s.store.Delete(r.Context(), id)) {
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) listNotes(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	f := store.ListFilter{Limit: defaultLimit}
	if q.Has("tag") {
		f.Tag, f.HasTag = q.Get("tag"), true
	}
	f.Query = q.Get("q")
	if q.Has("after") {
		after, ok := parseInt(q.Get("after"))
		if !ok {
			writeError(w, http.StatusBadRequest, "after must be an integer")
			return
		}
		f.After, f.HasAfter = after, true
	}
	if q.Has("limit") {
		limit, ok := parseInt(q.Get("limit"))
		if !ok || limit < 1 || limit > maxLimit {
			writeError(w, http.StatusBadRequest, "limit must be an integer from 1 to 100")
			return
		}
		f.Limit = int(limit)
	}
	notes, err := s.store.List(r.Context(), f)
	if err != nil {
		s.internalError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"notes": notes})
}

func (s *Server) stats(w http.ResponseWriter, r *http.Request) {
	count, tags, err := s.store.Stats(r.Context())
	if err != nil {
		s.internalError(w, err)
		return
	}
	byTag := make(map[string]int64, len(tags))
	for _, t := range tags {
		byTag[t.Tag] = t.Count
	}
	writeJSON(w, http.StatusOK, map[string]any{"notes": count, "tags": byTag})
}

func (s *Server) tags(w http.ResponseWriter, r *http.Request) {
	tags, err := s.store.Tags(r.Context())
	if err != nil {
		s.internalError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"tags": tags})
}

// readNoteInput reads and validates the request body, writing a 400 response on failure.
func (s *Server) readNoteInput(w http.ResponseWriter, r *http.Request) (noteInput, bool) {
	data, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeError(w, http.StatusBadRequest, "request body too large")
		} else {
			writeError(w, http.StatusBadRequest, "could not read request body")
		}
		return noteInput{}, false
	}
	in, err := parseNoteInput(data)
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return noteInput{}, false
	}
	return in, true
}

// storeError writes a response for a non-nil store error and reports whether it did.
func (s *Server) storeError(w http.ResponseWriter, err error) bool {
	switch {
	case err == nil:
		return false
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusNotFound, "note not found")
	default:
		s.internalError(w, err)
	}
	return true
}

func (s *Server) internalError(w http.ResponseWriter, err error) {
	s.log.Error("request failed", "err", err)
	writeError(w, http.StatusInternalServerError, "internal error")
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	data, err := json.Marshal(v)
	if err != nil {
		http.Error(w, `{"error":"internal error"}`, http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(data)
}

package api

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"notes/internal/store"
)

func newTestServer(t *testing.T, dbPath string) *httptest.Server {
	t.Helper()
	st, err := store.Open(context.Background(), dbPath)
	if err != nil {
		t.Fatal(err)
	}
	srv := httptest.NewServer(New(st, slog.New(slog.DiscardHandler)))
	t.Cleanup(func() {
		srv.Close()
		st.Close()
	})
	return srv
}

func do(t *testing.T, srv *httptest.Server, method, path, body string) (int, string) {
	t.Helper()
	req, err := http.NewRequest(method, srv.URL+path, strings.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	resp, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	data, _ := io.ReadAll(resp.Body)
	return resp.StatusCode, string(data)
}

func expect(t *testing.T, srv *httptest.Server, method, path, body string, wantStatus int, wantBody string) {
	t.Helper()
	status, got := do(t, srv, method, path, body)
	if status != wantStatus {
		t.Fatalf("%s %s: status %d, want %d (body %s)", method, path, status, wantStatus, got)
	}
	if wantBody != "" && got != wantBody {
		t.Fatalf("%s %s: body %s, want %s", method, path, got, wantBody)
	}
}

func TestAPI(t *testing.T) {
	srv := newTestServer(t, filepath.Join(t.TempDir(), "notes.db"))

	expect(t, srv, "GET", "/health", "", 200, "ok")
	expect(t, srv, "POST", "/notes", `{"title":"Hello","body":"World","tags":["b","a"]}`, 201, `{"id":1,"title":"Hello","body":"World","tags":["a","b"]}`)
	expect(t, srv, "POST", "/notes", `{"title":"second","body":"hello 100%","tags":["a"]}`, 201, "")
	expect(t, srv, "POST", "/notes", `{"title":"third"}`, 201, "")

	expect(t, srv, "GET", "/notes?q=HELLO", "", 200, `{"notes":[{"id":1,"title":"Hello","body":"World","tags":["a","b"]},{"id":2,"title":"second","body":"hello 100%","tags":["a"]}]}`)
	expect(t, srv, "GET", "/notes?q=%25", "", 200, `{"notes":[{"id":2,"title":"second","body":"hello 100%","tags":["a"]}]}`)
	expect(t, srv, "GET", "/notes?q=_", "", 200, `{"notes":[]}`)
	expect(t, srv, "GET", "/notes?tag=b", "", 200, `{"notes":[{"id":1,"title":"Hello","body":"World","tags":["a","b"]}]}`)
	expect(t, srv, "GET", "/notes?tag=a&after=1&limit=1", "", 200, `{"notes":[{"id":2,"title":"second","body":"hello 100%","tags":["a"]}]}`)
	expect(t, srv, "GET", "/notes?limit=101", "", 400, "")
	expect(t, srv, "GET", "/notes?limit=x", "", 400, "")
	expect(t, srv, "GET", "/notes?after=x", "", 400, "")

	expect(t, srv, "GET", "/tags", "", 200, `{"tags":[{"tag":"a","count":2},{"tag":"b","count":1}]}`)
	expect(t, srv, "DELETE", "/notes/1", "", 204, "")
	expect(t, srv, "GET", "/stats", "", 200, `{"notes":2,"tags":{"a":1}}`)
	expect(t, srv, "PUT", "/notes/2", `{"title":"x"}`, 200, `{"id":2,"title":"x","body":"","tags":[]}`)
	expect(t, srv, "GET", "/stats", "", 200, `{"notes":2,"tags":{}}`)

	expect(t, srv, "DELETE", "/notes", "", 405, "")
	expect(t, srv, "POST", "/notes/2", "", 405, "")
	expect(t, srv, "POST", "/stats", "", 405, "")
	expect(t, srv, "GET", "/notes/2/x", "", 404, "")
	expect(t, srv, "PUT", "/notes/abc", `{"title":"x"}`, 404, "")
}

func TestPersistenceAndIDsNeverReused(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "notes.db")
	srv := newTestServer(t, dbPath)
	expect(t, srv, "POST", "/notes", `{"title":"a"}`, 201, "")
	expect(t, srv, "POST", "/notes", `{"title":"b","tags":["t"]}`, 201, "")
	expect(t, srv, "DELETE", "/notes/2", "", 204, "")
	srv.Close()

	srv2 := newTestServer(t, dbPath)
	expect(t, srv2, "GET", "/notes/1", "", 200, `{"id":1,"title":"a","body":"","tags":[]}`)
	expect(t, srv2, "POST", "/notes", `{"title":"c"}`, 201, `{"id":3,"title":"c","body":"","tags":[]}`)
}

func TestConcurrentCreates(t *testing.T) {
	srv := newTestServer(t, filepath.Join(t.TempDir(), "notes.db"))
	const n = 100
	var wg sync.WaitGroup
	errs := make(chan error, n)
	for i := range n {
		wg.Go(func() {
			status, body := do(t, srv, "POST", "/notes", fmt.Sprintf(`{"title":"n%d","tags":["t"]}`, i))
			if status != 201 {
				errs <- fmt.Errorf("status %d: %s", status, body)
			}
		})
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Fatal(err)
	}
	_, body := do(t, srv, "GET", "/stats", "")
	var stats struct {
		Notes int            `json:"notes"`
		Tags  map[string]int `json:"tags"`
	}
	if err := json.Unmarshal([]byte(body), &stats); err != nil {
		t.Fatal(err)
	}
	if stats.Notes != n || stats.Tags["t"] != n {
		t.Fatalf("stats = %+v, want %d notes", stats, n)
	}
}

package api

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"slices"
	"strings"
	"unicode/utf8"
)

const (
	maxTitleLen = 200
	maxTagLen   = 32
)

// noteInput is a validated create/update request.
type noteInput struct {
	Title string
	Body  string
	Tags  []string
}

// validationError is a client error reported as 400.
type validationError struct{ msg string }

func (e *validationError) Error() string { return e.msg }

func invalid(format string, args ...any) error {
	return &validationError{msg: fmt.Sprintf(format, args...)}
}

// parseNoteInput decodes and validates a note request body.
func parseNoteInput(data []byte) (noteInput, error) {
	var fields map[string]json.RawMessage
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&fields); err != nil || fields == nil {
		return noteInput{}, invalid("request body must be a JSON object")
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return noteInput{}, invalid("request body must be a single JSON object")
	}

	var in noteInput

	raw, ok := fields["title"]
	if !ok {
		return noteInput{}, invalid("title is required")
	}
	title, ok := decodeString(raw)
	if !ok {
		return noteInput{}, invalid("title must be a string")
	}
	in.Title = strings.TrimSpace(title)
	if n := utf8.RuneCountInString(in.Title); n < 1 || n > maxTitleLen {
		return noteInput{}, invalid("title must be 1-%d characters", maxTitleLen)
	}

	if raw, ok := fields["body"]; ok {
		if in.Body, ok = decodeString(raw); !ok {
			return noteInput{}, invalid("body must be a string")
		}
	}

	in.Tags = []string{}
	if raw, ok := fields["tags"]; ok {
		tags, err := parseTags(raw)
		if err != nil {
			return noteInput{}, err
		}
		in.Tags = tags
	}
	return in, nil
}

// decodeString decodes raw as a JSON string; null and other types are rejected.
func decodeString(raw json.RawMessage) (string, bool) {
	if len(raw) == 0 || raw[0] != '"' {
		return "", false
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return "", false
	}
	return s, true
}

func parseTags(raw json.RawMessage) ([]string, error) {
	if len(raw) == 0 || raw[0] != '[' {
		return nil, invalid("tags must be an array of strings")
	}
	var items []json.RawMessage
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil, invalid("tags must be an array of strings")
	}
	tags := make([]string, 0, len(items))
	for _, item := range items {
		t, ok := decodeString(item)
		if !ok {
			return nil, invalid("tags must be an array of strings")
		}
		if !validTag(t) {
			return nil, invalid("invalid tag %q: must be 1-%d characters from a-z, 0-9 and -", t, maxTagLen)
		}
		tags = append(tags, t)
	}
	slices.Sort(tags)
	return slices.Compact(tags), nil
}

func validTag(t string) bool {
	if len(t) < 1 || len(t) > maxTagLen {
		return false
	}
	for i := 0; i < len(t); i++ {
		c := t[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

// parsePositiveID parses a note id path segment: decimal digits only, value ≥ 1.
func parsePositiveID(s string) (int64, bool) {
	n, ok := parseDigits(s)
	return n, ok && n >= 1
}

// parseDigits parses a non-empty run of ASCII digits that fits in int64.
func parseDigits(s string) (int64, bool) {
	if s == "" {
		return 0, false
	}
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		d := int64(c - '0')
		if n > (1<<63-1-d)/10 {
			return 0, false
		}
		n = n*10 + d
	}
	return n, true
}

// parseInt parses an optionally negative decimal integer that fits in int64.
func parseInt(s string) (int64, bool) {
	if rest, ok := strings.CutPrefix(s, "-"); ok {
		n, ok := parseDigits(rest)
		return -n, ok
	}
	return parseDigits(s)
}

package api

import (
	"slices"
	"strings"
	"testing"
)

func TestParseNoteInput(t *testing.T) {
	tests := []struct {
		name    string
		body    string
		want    noteInput
		wantErr bool
	}{
		{name: "minimal", body: `{"title":"a"}`, want: noteInput{Title: "a", Tags: []string{}}},
		{name: "trim and dedupe", body: ` {"title":"  x  ","body":"b","tags":["z","a","z"]} `, want: noteInput{Title: "x", Body: "b", Tags: []string{"a", "z"}}},
		{name: "200 runes", body: `{"title":"` + strings.Repeat("é", 200) + `"}`, want: noteInput{Title: strings.Repeat("é", 200), Tags: []string{}}},
		{name: "201 runes", body: `{"title":"` + strings.Repeat("a", 201) + `"}`, wantErr: true},
		{name: "invalid json", body: `{"title":`, wantErr: true},
		{name: "trailing data", body: `{"title":"a"} {}`, wantErr: true},
		{name: "array", body: `[]`, wantErr: true},
		{name: "null", body: `null`, wantErr: true},
		{name: "empty", body: ``, wantErr: true},
		{name: "missing title", body: `{}`, wantErr: true},
		{name: "blank title", body: `{"title":"   "}`, wantErr: true},
		{name: "numeric title", body: `{"title":1}`, wantErr: true},
		{name: "null title", body: `{"title":null}`, wantErr: true},
		{name: "numeric body", body: `{"title":"a","body":3}`, wantErr: true},
		{name: "tags not array", body: `{"title":"a","tags":"x"}`, wantErr: true},
		{name: "tag not string", body: `{"title":"a","tags":[1]}`, wantErr: true},
		{name: "tag uppercase", body: `{"title":"a","tags":["Bad"]}`, wantErr: true},
		{name: "tag empty", body: `{"title":"a","tags":[""]}`, wantErr: true},
		{name: "tag too long", body: `{"title":"a","tags":["` + strings.Repeat("a", 33) + `"]}`, wantErr: true},
		{name: "tag max length", body: `{"title":"a","tags":["` + strings.Repeat("a", 32) + `"]}`, want: noteInput{Title: "a", Tags: []string{strings.Repeat("a", 32)}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parseNoteInput([]byte(tt.body))
			if (err != nil) != tt.wantErr {
				t.Fatalf("err = %v, wantErr %v", err, tt.wantErr)
			}
			if err != nil {
				return
			}
			if got.Title != tt.want.Title || got.Body != tt.want.Body || !slices.Equal(got.Tags, tt.want.Tags) {
				t.Fatalf("got %+v, want %+v", got, tt.want)
			}
		})
	}
}

func TestParsePositiveID(t *testing.T) {
	for s, want := range map[string]bool{"1": true, "42": true, "0": false, "-1": false, "+1": false, "abc": false, "": false, "1.0": false, "99999999999999999999": false} {
		if _, ok := parsePositiveID(s); ok != want {
			t.Errorf("parsePositiveID(%q) ok = %v, want %v", s, ok, want)
		}
	}
}

// Package store persists notes in a SQLite database.
package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"net/url"
	"strings"

	_ "modernc.org/sqlite" // registers the "sqlite" driver
)

// ErrNotFound is returned when a note does not exist.
var ErrNotFound = errors.New("note not found")

// Note is a stored note.
type Note struct {
	ID    int64    `json:"id"`
	Title string   `json:"title"`
	Body  string   `json:"body"`
	Tags  []string `json:"tags"`
}

// TagCount is the number of notes carrying a tag.
type TagCount struct {
	Tag   string `json:"tag"`
	Count int64  `json:"count"`
}

// ListFilter selects notes for List. Zero values mean "no filter".
type ListFilter struct {
	Tag      string
	HasTag   bool
	Query    string
	After    int64
	HasAfter bool
	Limit    int
}

// Store is a SQLite-backed note store. It is safe for concurrent use.
type Store struct {
	db *sql.DB
}

const schema = `
CREATE TABLE IF NOT EXISTS notes (
	id    INTEGER PRIMARY KEY AUTOINCREMENT,
	title TEXT NOT NULL,
	body  TEXT NOT NULL,
	tags  TEXT NOT NULL DEFAULT '[]'
);
CREATE TABLE IF NOT EXISTS note_tags (
	note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
	tag     TEXT NOT NULL,
	PRIMARY KEY (note_id, tag)
) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS note_tags_tag ON note_tags(tag, note_id);
`

// Open opens (creating if needed) the database at path and ensures the schema exists.
func Open(ctx context.Context, path string) (*Store, error) {
	q := url.Values{}
	q.Add("_pragma", "busy_timeout(10000)")
	q.Add("_pragma", "journal_mode(WAL)")
	q.Add("_pragma", "synchronous(NORMAL)")
	q.Add("_pragma", "foreign_keys(ON)")
	q.Set("_txlock", "immediate")
	dsn := "file:" + (&url.URL{Path: path}).EscapedPath() + "?" + q.Encode()

	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open database: %w", err)
	}
	db.SetMaxOpenConns(8)
	db.SetMaxIdleConns(8)
	if _, err := db.ExecContext(ctx, schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("create schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Close closes the database.
func (s *Store) Close() error { return s.db.Close() }

// Create inserts a new note and returns it with its assigned id.
func (s *Store) Create(ctx context.Context, title, body string, tags []string) (Note, error) {
	n := Note{Title: title, Body: body, Tags: tags}
	err := s.withTx(ctx, func(tx *sql.Tx) error {
		tagsJSON, err := json.Marshal(tags)
		if err != nil {
			return err
		}
		res, err := tx.ExecContext(ctx, `INSERT INTO notes (title, body, tags) VALUES (?, ?, ?)`, title, body, string(tagsJSON))
		if err != nil {
			return err
		}
		if n.ID, err = res.LastInsertId(); err != nil {
			return err
		}
		return insertTags(ctx, tx, n.ID, tags)
	})
	if err != nil {
		return Note{}, fmt.Errorf("create note: %w", err)
	}
	return n, nil
}

// Update replaces the note with the given id.
func (s *Store) Update(ctx context.Context, id int64, title, body string, tags []string) (Note, error) {
	err := s.withTx(ctx, func(tx *sql.Tx) error {
		tagsJSON, err := json.Marshal(tags)
		if err != nil {
			return err
		}
		res, err := tx.ExecContext(ctx, `UPDATE notes SET title = ?, body = ?, tags = ? WHERE id = ?`, title, body, string(tagsJSON), id)
		if err != nil {
			return err
		}
		if n, err := res.RowsAffected(); err != nil {
			return err
		} else if n == 0 {
			return ErrNotFound
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM note_tags WHERE note_id = ?`, id); err != nil {
			return err
		}
		return insertTags(ctx, tx, id, tags)
	})
	if errors.Is(err, ErrNotFound) {
		return Note{}, err
	}
	if err != nil {
		return Note{}, fmt.Errorf("update note %d: %w", id, err)
	}
	return Note{ID: id, Title: title, Body: body, Tags: tags}, nil
}

// Delete removes the note with the given id.
func (s *Store) Delete(ctx context.Context, id int64) error {
	err := s.withTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, `DELETE FROM note_tags WHERE note_id = ?`, id); err != nil {
			return err
		}
		res, err := tx.ExecContext(ctx, `DELETE FROM notes WHERE id = ?`, id)
		if err != nil {
			return err
		}
		if n, err := res.RowsAffected(); err != nil {
			return err
		} else if n == 0 {
			return ErrNotFound
		}
		return nil
	})
	if err != nil && !errors.Is(err, ErrNotFound) {
		return fmt.Errorf("delete note %d: %w", id, err)
	}
	return err
}

// Get returns the note with the given id.
func (s *Store) Get(ctx context.Context, id int64) (Note, error) {
	row := s.db.QueryRowContext(ctx, `SELECT id, title, body, tags FROM notes WHERE id = ?`, id)
	n, err := scanNote(row)
	if errors.Is(err, sql.ErrNoRows) {
		return Note{}, ErrNotFound
	}
	if err != nil {
		return Note{}, fmt.Errorf("get note %d: %w", id, err)
	}
	return n, nil
}

// List returns notes matching f, ordered by id ascending.
func (s *Store) List(ctx context.Context, f ListFilter) ([]Note, error) {
	var (
		where []string
		args  []any
	)
	if f.HasTag {
		where = append(where, `id IN (SELECT note_id FROM note_tags WHERE tag = ?)`)
		args = append(args, f.Tag)
	}
	if f.Query != "" {
		// SQLite's built-in lower() folds ASCII letters only, which is exactly what we want.
		where = append(where, `(instr(lower(title), lower(?)) > 0 OR instr(lower(body), lower(?)) > 0)`)
		args = append(args, f.Query, f.Query)
	}
	if f.HasAfter {
		where = append(where, `id > ?`)
		args = append(args, f.After)
	}
	query := `SELECT id, title, body, tags FROM notes`
	if len(where) > 0 {
		query += ` WHERE ` + strings.Join(where, ` AND `)
	}
	query += ` ORDER BY id ASC LIMIT ?`
	args = append(args, f.Limit)

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("list notes: %w", err)
	}
	defer rows.Close()
	notes := []Note{}
	for rows.Next() {
		n, err := scanNote(rows)
		if err != nil {
			return nil, fmt.Errorf("list notes: %w", err)
		}
		notes = append(notes, n)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list notes: %w", err)
	}
	return notes, nil
}

// Stats returns the number of notes and the per-tag note counts, from one consistent snapshot.
func (s *Store) Stats(ctx context.Context) (int64, []TagCount, error) {
	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return 0, nil, fmt.Errorf("stats: %w", err)
	}
	defer tx.Rollback()

	var count int64
	if err := tx.QueryRowContext(ctx, `SELECT count(*) FROM notes`).Scan(&count); err != nil {
		return 0, nil, fmt.Errorf("stats: %w", err)
	}
	tags, err := tagCounts(ctx, tx)
	if err != nil {
		return 0, nil, fmt.Errorf("stats: %w", err)
	}
	return count, tags, nil
}

// Tags returns per-tag note counts ordered by count descending, then tag ascending.
func (s *Store) Tags(ctx context.Context) ([]TagCount, error) {
	tags, err := tagCounts(ctx, s.db)
	if err != nil {
		return nil, fmt.Errorf("tags: %w", err)
	}
	return tags, nil
}

type querier interface {
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
}

func tagCounts(ctx context.Context, q querier) ([]TagCount, error) {
	rows, err := q.QueryContext(ctx,
		`SELECT tag, count(*) AS c FROM note_tags GROUP BY tag ORDER BY c DESC, tag ASC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []TagCount{}
	for rows.Next() {
		var tc TagCount
		if err := rows.Scan(&tc.Tag, &tc.Count); err != nil {
			return nil, err
		}
		out = append(out, tc)
	}
	return out, rows.Err()
}

type scanner interface {
	Scan(dest ...any) error
}

func scanNote(sc scanner) (Note, error) {
	var (
		n        Note
		tagsJSON string
	)
	if err := sc.Scan(&n.ID, &n.Title, &n.Body, &tagsJSON); err != nil {
		return Note{}, err
	}
	if err := json.Unmarshal([]byte(tagsJSON), &n.Tags); err != nil {
		return Note{}, fmt.Errorf("decode tags of note %d: %w", n.ID, err)
	}
	if n.Tags == nil {
		n.Tags = []string{}
	}
	return n, nil
}

func insertTags(ctx context.Context, tx *sql.Tx, id int64, tags []string) error {
	if len(tags) == 0 {
		return nil
	}
	stmt, err := tx.PrepareContext(ctx, `INSERT INTO note_tags (note_id, tag) VALUES (?, ?)`)
	if err != nil {
		return err
	}
	defer stmt.Close()
	for _, t := range tags {
		if _, err := stmt.ExecContext(ctx, id, t); err != nil {
			return err
		}
	}
	return nil
}

func (s *Store) withTx(ctx context.Context, fn func(*sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := fn(tx); err != nil {
		_ = tx.Rollback()
		return err
	}
	return tx.Commit()
}

// Command app serves a small SQLite-backed notes store over HTTP.
//
// Usage: NOTES_DB=/path/to/notes.db ./app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"notes/internal/api"
	"notes/internal/store"
)

func main() {
	log := slog.New(slog.NewTextHandler(os.Stderr, nil))
	if err := run(log); err != nil {
		log.Error("fatal", "err", err)
		os.Exit(1)
	}
}

func run(log *slog.Logger) error {
	if len(os.Args) != 2 {
		return fmt.Errorf("usage: %s <port>", os.Args[0])
	}
	port, err := strconv.ParseUint(os.Args[1], 10, 16)
	if err != nil {
		return fmt.Errorf("invalid port %q", os.Args[1])
	}
	dbPath := os.Getenv("NOTES_DB")
	if dbPath == "" {
		return errors.New("NOTES_DB is not set")
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	st, err := store.Open(ctx, dbPath)
	if err != nil {
		return err
	}
	defer st.Close()

	ln, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10)))
	if err != nil {
		return err
	}
	srv := &http.Server{
		Handler:           api.New(st, log),
		ReadHeaderTimeout: 10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	log.Info("listening", "addr", ln.Addr().String(), "db", dbPath)

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	return srv.Shutdown(shutdownCtx)
}
